37	  // (implementation-defined on a real trap / dirty bits -> false positives).
38	  cmp(r, "mepc", ref.mepc, got.mepc);
39	  cmp(r, "mcause", ref.mcause, got.mcause);
40	
41	  // Round-trip M-mode CSRs, hybrid policy only: mscratch (L23) and mtval/mie
42	  // (L24) are restored at resume and re-read at drain, so a trap-free ROI must
43	  // match the oracle on them. The lock-step path is reset-vs-reset
44	  // (implementation-defined reset values), so it excludes them. mip is excluded
45	  // in BOTH: its pending bits are hardware/platform-driven (timer/external) and
46	  // diverge between QEMU's functional clock and vsim's cycle clock even with no
47	  // trap (it still round-trips into the drained record, just not the verifier).
48	  if (!compare_trap_cause) {
49	    cmp(r, "mscratch", ref.mscratch, got.mscratch);
50	    cmp(r, "mtval", ref.mtval, got.mtval);
51	    cmp(r, "mie", ref.mie, got.mie);
52	  }
53	
54	  for (int i = 0; i < 32; ++i)
55	    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);
56	
57	  if (ref.flags & HYBRID_FLAG_FP) {
58	    for (int i = 0; i < 32; ++i)
59	      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
60	    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
61	  }
62	
63	  if (ref.flags & HYBRID_FLAG_V) {
64	    cmp(r, "vstart", ref.vstart, got.vstart);
65	    cmp(r, "vtype", ref.vtype, got.vtype);
66	    cmp(r, "vl", ref.vl, got.vl);
67	    cmp(r, "vlenb", ref.vlenb, got.vlenb);
68	    cmp(r, "vxsat", ref.vxsat, got.vxsat);
69	    cmp(r, "vxrm", ref.vxrm, got.vxrm);
70	    cmp(r, "vcsr", ref.vcsr, got.vcsr);
71	
72	    // One compared "field" per vector register; report the first differing
73	    // byte as "v<i>[<byte>]".
74	    for (int i = 0; i < 32; ++i) {
75	      ++r.compared;
76	      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
77	      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
78	      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
79	        if (a[j] != b[j]) {
80	          r.diffs.push_back({"v" + std::to_string(i) + "[" +
81	                                 std::to_string(j) + "]",
82	                             a[j], b[j]});
83	          break;
84	        }
85	      }
86	    }
87	  }
88	
89	  return r;
